  ($c$policy.booking.heading$c$, $c$policies$c$, $c$السياسات — الحجز والتأكيد: العنوان$c$, 48, $c$policies.json$c$, array[$c$page$c$, $c$sections$c$, $c$0$c$, $c$heading_ar$c$]::text[], array[$c$page$c$, $c$sections$c$, $c$0$c$, $c$heading_en$c$]::text[], $c$[{"path": ["page", "sections", "0", "id"], "value": "booking"}]$c$::jsonb, 80, false, $c${}$c$::jsonb, $c$الحجز والتأكيد$c$, $c$Booking and confirmation$c$, $c$الحجز والتأكيد$c$, $c$Booking and confirmation$c$),
  ($c$policy.booking.body$c$, $c$policies$c$, $c$السياسات — الحجز والتأكيد: النص$c$, 49, $c$policies.json$c$, array[$c$page$c$, $c$sections$c$, $c$0$c$, $c$body_ar$c$]::text[], array[$c$page$c$, $c$sections$c$, $c$0$c$, $c$body_en$c$]::text[], $c$[{"path": ["page", "sections", "0", "id"], "value": "booking"}]$c$::jsonb, 1500, true, $c${}$c$::jsonb, $c$يمكن تأكيد الحجز عبر الموقع بطريقتين. إذا ظهرت علامة «تأكيد فوري» بعد اختيار التواريخ، يتأكد حجزك مباشرة عند الإرسال، ويصلك التأكيد عبر الواتساب وعبر البريد الإلكتروني إن أدخلته، ويكون الإجمالي المعروض قبل الإرسال هو المستحق. وإذا لم تظهر هذه العلامة، فما ترسله طلب حجز يراجعه فريق الاستقبال، ثم يؤكد لك التوافر والسعر النهائي عبر الواتساب أو البريد الإلكتروني. الأسعار المعروضة على الموقع لليلة الواحدة وشاملة ضريبة القيمة المضافة.$c$, $c$A website booking is confirmed in one of two ways. If you see “Instant confirmation” after choosing your dates, your booking is confirmed as soon as you submit it; the confirmation reaches you on WhatsApp, and by email if you gave one, and the total shown before you submit is the amount due. Otherwise, what you send is a booking request: our reception team reviews it and confirms availability and the final price with you on WhatsApp or by email. Prices on the website are per night and include VAT.$c$, $c$يمكن تأكيد الحجز عبر الموقع بطريقتين. إذا ظهرت علامة «تأكيد فوري» بعد اختيار التواريخ، يتأكد حجزك مباشرة عند الإرسال، ويصلك التأكيد عبر الواتساب وعبر البريد الإلكتروني إن أدخلته، ويكون الإجمالي المعروض قبل الإرسال هو المستحق. وإذا لم تظهر هذه العلامة، فما ترسله طلب حجز يراجعه فريق الاستقبال، ثم يؤكد لك التوافر والسعر النهائي عبر الواتساب أو البريد الإلكتروني. الأسعار المعروضة على الموقع لليلة الواحدة وشاملة ضريبة القيمة المضافة.$c$, $c$A website booking is confirmed in one of two ways. If you see “Instant confirmation” after choosing your dates, your booking is confirmed as soon as you submit it; the confirmation reaches you on WhatsApp, and by email if you gave one, and the total shown before you submit is the amount due. Otherwise, what you send is a booking request: our reception team reviews it and confirms availability and the final price with you on WhatsApp or by email. Prices on the website are per night and include VAT.$c$),
